window.TRILLION_PILOT = {"schemaVersion":1,"revision":"2026-11-03-40-design-pilot-precedent","jurisdiction":"CA","electionDate":"2026-11-03","measure":{"number":"40","title":"IMPOSES ONE-TIME TAX ON CERTAIN TAXPAYERS. INITIATIVE CONSTITUTIONAL AMENDMENT AND STATUTE.","url":"https://voterguide.sos.ca.gov/propositions/40/","guideHash":"0003f350db84766d1d5e24ab784cdc9d40dfe08b0799bea0b47c60ba2b51401c"},"rootId":"root","summary":{"text":"Proposition 40 imposes a **5% net-worth tax** for tax year 2026 on individuals with $1 billion or more who are California residents on January 1, 2026, and applicable trusts. Wealth is valued December 31, 2026. After administrative expenses, **90% goes to health care** and 10% to education and food assistance.","quotes":[{"sourceId":"law-40","locator":"SEC. 7, Revenue and Taxation Code §50301(a)–(b)","text":"An excise tax is imposed for tax year 2026 … on the activity of sustaining excessive accumulations of … wealth by applicable individuals with net worth of one … billion dollars ($1,000,000,000) or more, and on … applicable trusts. … the tax imposed is 5 percent of … the net worth of such individual or trust."},{"sourceId":"law-40","locator":"SEC. 7, Revenue and Taxation Code §50308(a), (n)–(o)","text":"“Applicable individual” means, for the 2026 tax … year, any individual who is a resident of this state, within … the meaning of Sections 17014 and 17015.5, as of the … tax obligation date specified in subdivision (n). … “Tax obligation date” means January 1, 2026. … “Valuation date” means December 31, 2026."},{"sourceId":"law-40","locator":"SEC. 7, Revenue and Taxation Code §50301(a)","text":"the amount of net worth subject to tax is … measured as of the valuation date."},{"sourceId":"law-40","locator":"SEC. 5, Government Code §16355(b)(1)–(2)","text":"After accounting for administrative expenses as … provided in subdivision (e), the Controller shall allocate … and transfer the remaining moneys in the Reserve Fund … as follows: … Ninety percent shall be allocated to the Billionaire … Tax Health Account for health care funding … Ten percent shall be allocated to the Billionaire Tax … Education and Food Assistance Account for education- … related and food assistance expenditures"}],"generation":{"promptVersion":"trillion-summary-v1","model":"openai-compatible:gpt-6.1-sol","generatedAt":"2026-10-13T13:57:53.542Z"}},"nodes":[{"id":"root","kind":"root","label":"How should I vote on Prop 40?","title":"How should I vote on Prop 40?","body":"This is your decision. The graph collects what the measure says, what people argue, and where they disagree. It does not add up to an answer.","quotes":[]},{"id":"b-what","kind":"branch","label":"What does it actually do?","title":"What does it actually do?","body":"The measure text, quoted section by section, with the Legislative Analyst's reading.","quotes":[]},{"id":"b-who","kind":"branch","label":"Who's behind it?","title":"Who's behind it?","body":"Who signed the official arguments, and what each side says about the other.","quotes":[]},{"id":"b-when","kind":"branch","label":"When?","title":"When?","body":"Dates that decide who owes the tax and when courts rule. Dates in the text, not retrieval dates.","quotes":[]},{"id":"b-how","kind":"branch","label":"How can I act?","title":"How can I act?","body":"Official ways to take part.","quotes":[]},{"id":"x-revenue","kind":"crux","label":"How much would it raise?","title":"How much money would it actually raise?","body":"A dispute about facts and estimates. The campaigns' numbers and the Legislative Analyst's differ by tens of billions.","quotes":[],"dispute":"facts"},{"id":"x-fair","kind":"crux","label":"Is it fair?","title":"Is it fair to tax wealth instead of income?","body":"Mostly a values question. Evidence can inform it, but people weigh fairness differently.","quotes":[],"dispute":"values"},{"id":"x-expand","kind":"crux","label":"Could it spread?","title":"Could it spread beyond billionaires?","body":"A dispute about how to read the measure's amendment clause and its exemptions.","quotes":[],"dispute":"reading"},{"id":"x-money","kind":"crux","label":"Where does the money go?","title":"Where would the money go?","body":"A dispute about what the spending rules require and what they leave to the Legislature.","quotes":[],"dispute":"reading"},{"id":"x-effect","kind":"crux","label":"Will it take effect?","title":"Would it take effect, and for how long?","body":"Depends on Props 41 and 42, on court rulings, and on how long payments stretch.","quotes":[],"dispute":"legal"},{"id":"t-tax","kind":"provision","label":"5% tax on $1B+ net worth","title":"A **5% tax on net worth** of $1 billion or more, for tax year 2026.","quotes":[{"sourceId":"law-40","locator":"Prop 40 §50301(a)–(b) · Voter guide p. 138","text":"An excise tax is imposed for tax year 2026 on the activity of sustaining excessive accumulations of wealth by applicable individuals with net worth of one billion dollars ($1,000,000,000) or more, and on applicable trusts. … the tax imposed is 5 percent of the net worth of such individual or trust."}]},{"id":"t-date","kind":"provision","label":"Owed if resident Jan 1, 2026","title":"Who owes is **fixed on January 1, 2026**. Wealth is measured on December 31, 2026.","quotes":[{"sourceId":"law-40","locator":"§50306(a) · Voter guide p. 143","text":"One hundred percent of any tax imposed under Sections 50301 and 50304 is apportioned to California for all applicable individuals and applicable trusts, without reduction or multiplier based on residency history"},{"sourceId":"law-40","locator":"§50308(n)–(o) · Voter guide p. 145","text":"“Tax obligation date” means January 1, 2026. (o) “Valuation date” means December 31, 2026."}]},{"id":"t-installments","kind":"provision","label":"Optional 5-year payment plan","title":"Payers can **spread it over five years**, with a 7.5% annual charge on the unpaid balance.","quotes":[{"sourceId":"law-40","locator":"Prop 40 §50301(c) · Voter guide p. 139","text":"… (2) pay annually in five equal installments commencing in the year the tax is due, with each subsequent annual installment payment also being subject to an annual nondeductible deferral charge of 7.5 percent of the remaining unpaid balance."}]},{"id":"t-oda","kind":"provision","label":"Deferrals bind the estate","title":"Illiquid wealth can go into a **deferral account** that binds the payer's estate until settled.","quotes":[{"sourceId":"law-40","locator":"Prop 40 §50304(b) · Voter guide p. 142","text":"The contract shall be legally binding on the taxpayer, and also on the taxpayer’s estate and assigns, until either the taxpayer or the taxpayer’s estate or assigns reconciles and appropriately closes the ODA by fully liquidating the accumulated tax claims and then paying all tax due on the liquidated tax claims."}]},{"id":"t-retire","kind":"provision","label":"Pensions and IRAs exempt; big Roths aren't","title":"Pensions and IRAs are exempt. **Roth balances above $10 million** are not.","quotes":[{"sourceId":"law-40","locator":"§50303(c)(7)(A)–(B) · Voter guide p. 141","text":"Except as described in subparagraph (B), qualified pensions and individual retirement arrangements … (B) Amounts held in Roth IRA or other Roth-type retirement arrangements or any substantially similar accounts, except to the extent that the aggregate value in all of those accounts in which the taxpayer holds a beneficial interest, either directly or indirectly, exceeds ten million dollars ($10,000,000) in present value."}]},{"id":"t-realestate","kind":"provision","label":"Real estate excluded","title":"Directly held **real estate is left out** of net worth.","quotes":[{"sourceId":"law-40","locator":"§50303(c)(4) · Voter guide p. 141","text":"All interests in any real property held directly by a taxpayer or held via a revocable trust shall not be … included in net worth."}]},{"id":"t-amend","kind":"provision","label":"Legislature can amend by 2/3","title":"The Legislature can amend the act by a **two-thirds vote**, within the act's purposes.","quotes":[{"sourceId":"law-40","locator":"Prop 40 §50310 · Voter guide p. 145","text":"The Legislature may amend the 2026 Billionaire Tax Act, by statute passed in each house of the Legislature by rollcall vote entered in the journal, two-thirds of the membership concurring, if the statute is consistent with and furthers the purposes of the 2026 Billionaire Tax Act."}]},{"id":"t-purpose","kind":"provision","label":"Stated purpose: narrow, one-time","title":"The act states its purpose as a **narrow, one-time tax** on billionaire wealth.","quotes":[{"sourceId":"law-40","locator":"Prop 40 Sec. 3(d) · Voter guide p. 136","text":"The act raises funding for health care, education, and food assistance by imposing a narrowly applicable, one-time tax that is administratively feasible and efficient to enforce against all billionaires in the state."}]},{"id":"t-spend","kind":"provision","label":"90% health, 10% schools and food","title":"**90% goes to a health account**, 10% to education and food, appropriated by the Legislature.","quotes":[{"sourceId":"law-40","locator":"Prop 40 Gov. Code §16355(b)–(c) · Voter guide p. 137","text":"The Legislature shall have the authority to appropriate up to twenty-two billion five hundred million dollars ($22,500,000,000) each fiscal year from the Billionaire Tax Health Account and up to two billion five hundred million dollars ($2,500,000,000) each year from the Billionaire Tax Education and Food Assistance Account."}]},{"id":"t-supplant","kind":"provision","label":"Can't replace existing funding","title":"The money **can't replace existing** health, education, or food funding.","quotes":[{"sourceId":"law-40","locator":"Prop 40 Gov. Code §16355(d) · Voter guide p. 137","text":"The appropriation of funds from this measure shall not be used to supplant existing state funds for health care, education, or food assistance programs."}]},{"id":"t-limits","kind":"provision","label":"Outside spending and school limits","title":"The revenue sits **outside the state spending limit** and the school-funding formula.","quotes":[{"sourceId":"law-40","locator":"Prop 40 Art. XIII §37(e)–(f) · Voter guide p. 137","text":"… shall not be considered “General Fund revenues,” “state revenues,” “moneys,” or “proceeds of taxes” under Section 8 of Article XIII B for the purposes of any section of Article XIII B, or Section 8 or 8.5 of Article XVI."}]},{"id":"t-conflict40","kind":"provision","label":"Wins if it gets more votes","title":"Prop 40's own conflict rule: if it gets **more yes votes** than a conflicting measure, it prevails.","quotes":[{"sourceId":"law-40","locator":"Prop 40 Sec. 8 · Voter guide p. 147","text":"In the event that this measure receives a greater number of affirmative votes than a measure deemed to be in conflict with it, the provisions of this measure shall prevail in their entirety, and any conflicting provisions of the other measure or measures shall be null and void."}]},{"id":"t-reform","kind":"provision","label":"Courts may push dates later","title":"If a court rejects the 2026 dates, it should **move the tax to 2027 or later** rather than drop it.","quotes":[{"sourceId":"law-40","locator":"Prop 40 §50311(b) · Voter guide p. 145","text":"In reforming any dates or periods specified in the act, a court shall, to the maximum extent permitted by law, preserve the imposition of the tax for the 2026 tax year, or if that is not permissible then for 2027 or the earliest permissible subsequent year …"}]},{"id":"f-wealth","kind":"finding","label":"~200 billionaires, $2 trillion","title":"The measure's findings: **about 200 billionaires** holding $2 trillion.","quotes":[{"sourceId":"law-40","locator":"Prop 40 Findings, Sec. 2(r) · Voter guide p. 135","text":"California has around 200 billionaires who collectively possess an astonishing $2 trillion in wealth."}],"note":"This is a finding the measure's authors wrote, not a calculation in the operative law."},{"id":"f-rates","kind":"finding","label":"Billionaires 24% vs. average 30%","title":"The measure's findings: billionaires pay **24% of income** in all taxes; the average taxpayer pays 30%.","quotes":[{"sourceId":"law-40","locator":"Prop 40 Findings, Sec. 2(s) · Voter guide p. 135","text":"According to economic analysis and including all taxes at all levels of government, billionaires pay 24% of their income in taxes while the average taxpayer pays 30%."}],"note":"Cites Balkir, Saez, Yagan & Zucman, NBER Working Paper No. 34170 (2025)."},{"id":"l-revenue","kind":"analysis","label":"LAO: tens of billions","title":"LAO: probably **tens of billions**, spread across several years.","quotes":[{"sourceId":"analysis-40","locator":"LAO analysis of Prop 40","text":"The state probably would collect tens of billions of dollars from the wealth tax. This temporary increase in state tax collections would be spread across several years."}]},{"id":"l-income","kind":"analysis","label":"LAO: under $1B a year lost","title":"LAO: **some billionaires may leave**, cutting income tax by less than $1 billion a year.","quotes":[{"sourceId":"analysis-40","locator":"LAO analysis of Prop 40","text":"Billionaires may respond to a new wealth tax in ways that reduce their income tax payments. For example, some billionaires may decide to leave California. … These responses probably would reduce state revenues by less than $1 billion per year."}]},{"id":"a-100b","kind":"argument","label":"Raises ~$100B for health care","title":"It will raise **about $100 billion** for health care.","quotes":[{"sourceId":"arguments-40","locator":"Argument in favor of Prop 40","text":"It will raise about $100 billion to replace the funding Trump and his billionaire donors took from working people to line their pockets."}],"attribution":{"name":"Ballot argument for","signers":"Suzanne Jimenez (SEIU-UHW), Victoria Barron (Planned Parenthood of Pacific Southwest), Denise Robb (AFT Local 1521)"}},{"id":"a-fair","kind":"argument","label":"Billionaires pay lower rates","title":"Billionaires pay **lower tax rates** than working families.","quotes":[{"sourceId":"arguments-40","locator":"Argument in favor of Prop 40","text":"You pay your taxes out of every paycheck, but billionaires pay much lower rates than working families."}],"attribution":{"name":"Ballot argument for","signers":"Suzanne Jimenez (SEIU-UHW), Victoria Barron (Planned Parenthood of Pacific Southwest), Denise Robb (AFT Local 1521)"}},{"id":"a-25b","kind":"argument","label":"Costs $25B as the rich leave","title":"It will cost California **$25 billion** as wealthy residents leave.","quotes":[{"sourceId":"arguments-40","locator":"Argument against Prop 40","text":"A study by Stanford University economists found the tax will cost California $25 billion as the tax drives companies and wealthy residents out-of-state."}],"attribution":{"name":"Ballot argument against","signers":"René Bravo, M.D. (California Medical Association), Francisco Silva (California Primary Care Association), Dr. Debra Schade (California School Boards Association)"}},{"id":"a-expand","kind":"argument","label":"Could expand to everyone","title":"The Legislature could expand it to **everyone's savings, homes, and retirement funds**.","quotes":[{"sourceId":"arguments-40","locator":"Argument against Prop 40","text":"Independent legal analysis found Prop. 40 opens the door to expanding the tax to the assets of ALL Californians—to your savings, home equity and even retirement funds."}],"attribution":{"name":"Ballot argument against","signers":"René Bravo, M.D. (California Medical Association), Francisco Silva (California Primary Care Association), Dr. Debra Schade (California School Boards Association)"}},{"id":"a-only","kind":"argument","label":"Only ever billionaires","title":"It can't be applied to **anyone but billionaires**.","quotes":[{"sourceId":"arguments-40","locator":"Rebuttal to argument against Prop 40","text":"Prop. 40 is a BILLIONAIRE tax. It cannot be applied to anyone else—working people already pay more than their fair share."}],"attribution":{"name":"Rebuttal for","signers":"Suzanne Jimenez (SEIU-UHW), Victoria Barron (Planned Parenthood of Pacific Southwest), Denise Robb (AFT Local 1521)"}},{"id":"a-retire","kind":"argument","label":"First tax on retirement accounts","title":"It would be the first California **tax on retirement accounts**.","quotes":[{"sourceId":"arguments-40","locator":"Argument against Prop 40","text":"Prop. 40 would be the first in California history to tax retirement accounts—a dangerous precedent."}],"attribution":{"name":"Ballot argument against","signers":"René Bravo, M.D. (California Medical Association), Francisco Silva (California Primary Care Association), Dr. Debra Schade (California School Boards Association)"}},{"id":"a-schools","kind":"argument","label":"Shortchanges schools $3B a year","title":"It **shortchanges schools** by over $3 billion a year.","quotes":[{"sourceId":"arguments-40","locator":"Argument against Prop 40","text":"Exempts itself from voter-approved constitutional protections for schools, shortchanging classrooms over $3 billion annually."}],"attribution":{"name":"Ballot argument against","signers":"René Bravo, M.D. (California Medical Association), Francisco Silva (California Primary Care Association), Dr. Debra Schade (California School Boards Association)"}},{"id":"a-safeguards","kind":"argument","label":"No spending safeguards","title":"Nothing stops the money from **going to insurance companies**.","quotes":[{"sourceId":"arguments-40","locator":"Argument against Prop 40","text":"Includes no safeguards to prevent billions from going directly to health insurance companies and CEOs."}],"attribution":{"name":"Ballot argument against","signers":"René Bravo, M.D. (California Medical Association), Francisco Silva (California Primary Care Association), Dr. Debra Schade (California School Boards Association)"}},{"id":"a-onetime","kind":"argument","label":"One-time money, more taxes later","title":"It's one-time money, so **another tax will follow**.","quotes":[{"sourceId":"arguments-40","locator":"Argument against Prop 40","text":"This measure is a one-time tax that only provides temporary funds. When the money runs out, the politicians will be back with yet another tax."}],"attribution":{"name":"Ballot argument against","signers":"René Bravo, M.D. (California Medical Association), Francisco Silva (California Primary Care Association), Dr. Debra Schade (California School Boards Association)"}},{"id":"a-brin","kind":"argument","label":"One opponent spent $57M+","title":"One billionaire has spent **over $57 million** opposing it.","quotes":[{"sourceId":"arguments-40","locator":"Argument in favor of Prop 40","text":"Google founder and Trump donor Sergey Brin's wealth has DOUBLED to nearly $300 billion since Trump's election. Now he's spent over $57 million to oppose Prop. 40."}],"attribution":{"name":"Ballot argument for","signers":"Suzanne Jimenez (SEIU-UHW), Victoria Barron (Planned Parenthood of Pacific Southwest), Denise Robb (AFT Local 1521)"},"note":"No campaign-finance record is attached in this prototype. Spending figures should cite state filings before they count as evidence."},{"id":"g-retire","kind":"generated","label":"Both partly right on retirement","title":"Both sides are **partly right** about retirement accounts.","body":"The text exempts qualified pensions and IRAs, so most retirement savings are untouched. It does count Roth balances above a threshold the text sets, which taxes part of some retirement accounts.","quotes":[]},{"id":"g-retro","kind":"generated","label":"Fixed 10 months before the vote","title":"Who owes is decided by where they lived **ten months before the vote**.","body":"The tax obligation date is January 1, 2026. Voters decide on November 3, 2026. Someone who moved away in 2026 still owes in full.","quotes":[]},{"id":"g-nullify","kind":"generated","label":"Prop 41 or 42 could cancel it","title":"A yes on 40 **may not take effect** if Prop 41 or 42 gets more yes votes.","body":"Props 41 and 42 each declare Prop 40 in conflict. Whichever conflicting measure gets more yes votes prevails, so the Prop 40 result depends on two other records.","quotes":[]},{"id":"g-movers","kind":"generated","label":"Moving away doesn't help","title":"No. Leaving after January 1, 2026 **doesn't reduce the tax**, with one exception.","body":"The full tax is apportioned to California regardless of residency history. A payer can petition for a lower share by showing their wealth did not substantially accumulate in, and was not substantially sustained by, California.","quotes":[]},{"id":"q-expand","kind":"question","label":"Could a 2/3 vote widen it?","title":"Could a two-thirds vote extend this tax to people who aren't billionaires?","body":"Anticipated question. The text allows amendments that are “consistent with and furthers the purposes” of the act. Whether a broader tax would meet that test is a legal judgment nobody has answered here yet.","quotes":[]},{"id":"q-movers","kind":"question","label":"Can they move to avoid it?","title":"Can a billionaire avoid the tax by moving out of California?","body":"Anticipated question.","quotes":[]},{"id":"gl-wealth","kind":"shared","label":"Taxing untaxed gains is fair","title":"Taxing accumulated wealth is fair when gains go **untaxed until sale**.","body":"A shared claim about fairness. It is a value judgment, so evidence can inform it but can't settle it.","quotes":[]},{"id":"gl-flight","kind":"shared","label":"High earners move over taxes","title":"High earners **move away** in response to state taxes.","body":"A shared empirical claim. How large the effect is depends on the tax and the place.","quotes":[]},{"id":"gl-prospective","kind":"shared","label":"Taxes should only look forward","title":"Taxes should apply **only to what happens after** they're enacted.","body":"A shared principle about notice and fairness.","quotes":[]},{"id":"rec-41","kind":"record","label":"Prop 41: spending limit","title":"Prop 41: no new taxes **exempt from the state spending limit**","quotes":[{"sourceId":"law-41","locator":"Prop 41 Sec. 5(a)(1) · Voter guide p. 150","text":"In the event that this initiative measure appears on the same statewide election ballot as another initiative measure that … (B) contains a state tax that is exempted or excluded from the Government Spending Limitation, then that other initiative measure shall be deemed to be in conflict with this measure."}],"record":{"number":"41"}},{"id":"rec-42","kind":"record","label":"Prop 42: no retroactive taxes","title":"Prop 42: no new personal-property taxes and **no retroactive taxes**","quotes":[{"sourceId":"law-42","locator":"Prop 42 Art. VIII §2(a)(2) · Voter guide p. 151","text":"This subdivision also applies to a tax that is imposed on a taxpayer based upon their residency status on a date prior to the effective date of the tax."}],"record":{"number":"42"}},{"id":"w-for","kind":"fact","label":"Who signed for","title":"Official **argument for**: SEIU-UHW, Planned Parenthood of Pacific Southwest, AFT Local 1521 signers.","quotes":[]},{"id":"w-against","kind":"fact","label":"Who signed against","title":"Official **argument against**: California Medical Association, Primary Care Association, School Boards Association signers.","quotes":[]},{"id":"wh-election","kind":"fact","label":"Election: Nov 3, 2026","title":"Election day is **Tuesday, November 3, 2026**.","quotes":[]},{"id":"wh-review","kind":"provision","label":"60 days to sue","title":"Legal challenges must be filed **within 60 days**; courts aim to rule by November 1, 2027.","quotes":[{"sourceId":"law-40","locator":"Prop 40 §50314(c), (d)(4) · Voter guide p. 147","text":"A validation action shall not be filed more than 60 days after the approval of the act by the voters. … the California Supreme Court shall make every effort to resolve any review proceeding by November 1, 2027, or as soon as possible thereafter."}]},{"id":"h-vote","kind":"fact","label":"Vote on Nov 3","title":"Vote on Prop 40 on your **November 3, 2026 ballot**.","body":"Registration and return options are in the official voter guide.","quotes":[]},{"id":"h-private","kind":"fact","label":"Record your choice privately","title":"Record your own choice in ballot prep. It **stays private**.","body":"Your choice is never published or added to the graph.","quotes":[]},{"id":"x-history","kind":"crux","label":"Has this been tried before?","title":"Has this been tried before, and did it work?","body":"California has taxed its highest earners for a set purpose before. How those taxes raised and spent money bears on what this one would do, though none was a tax on wealth itself.","quotes":[],"dispute":"facts"},{"id":"p-mhsa","kind":"precedent","label":"2004: a tax on the rich for mental health","title":"Prop 63 (2004) added a **1 percent tax on incomes over $1 million** to expand mental health services.","quotes":[{"sourceId":"precedent-mhsa-audit","locator":"Report 2017-117, Summary, page 1","text":"In 2004 California voters approved Proposition 63—the Mental Health Services Act (MHSA)—to expand services and treatment for those who suffer from mental illness or are at risk of mental illness. The MHSA imposes a 1 percent income tax on individuals earning more than $1 million a year"}]},{"id":"p-unspent","kind":"precedent","label":"Audit: earmarked money sat unspent","title":"A 2018 state audit found local agencies had let **$231 million** in Prop 63 money go unspent, not counting reserves.","quotes":[{"sourceId":"precedent-mhsa-audit","locator":"Report 2017-117, Summary, page 1","text":"Health Care Services has not developed a process—known as reversion—to recover unspent MHSA funds from local mental health agencies after the statutory time frames for spending the funds have elapsed. As a result, the local mental health agencies have had less incentive to spend MHSA funds in a timely manner and had amassed unspent funds of $231 million—not including reserves—as of the end of fiscal year 2015–16"}]},{"id":"p-temporary","kind":"precedent","label":"A temporary tax that was extended","title":"Prop 30's tax increases on high earners were set to end after 2018; in 2016 voters approved Prop 55 to **extend them through 2030**.","quotes":[{"sourceId":"precedent-prop55","locator":"Proposition 55 analysis, Yes/No statement","text":"A YES vote on this measure means: Income tax increases on high-income taxpayers, which are scheduled to end after 2018, would instead be extended through 2030."}]},{"id":"p-volatile","kind":"precedent","label":"Taxes on the rich swing with markets","title":"The Legislative Analyst found revenue from high earners **hard to predict** because it depends on stock and other asset values.","quotes":[{"sourceId":"precedent-prop55","locator":"Proposition 55 analysis, Fiscal Effects: Taxes","text":"A large share of high-income taxpayers’ earnings comes from capital gains. These revenues depend heavily on future stock market and other asset values, which are difficult to predict."}]}],"edges":[{"id":"e1","from":"b-what","to":"root","type":"part"},{"id":"e2","from":"b-who","to":"root","type":"part"},{"id":"e3","from":"b-when","to":"root","type":"part"},{"id":"e4","from":"b-how","to":"root","type":"part"},{"id":"e10","from":"t-tax","to":"b-what","type":"detail"},{"id":"e11","from":"t-date","to":"b-what","type":"detail"},{"id":"e12","from":"t-retire","to":"b-what","type":"detail"},{"id":"e13","from":"t-realestate","to":"b-what","type":"detail"},{"id":"e14","from":"t-installments","to":"b-what","type":"detail"},{"id":"e15","from":"t-oda","to":"b-what","type":"detail"},{"id":"e16","from":"t-spend","to":"b-what","type":"detail"},{"id":"e17","from":"t-limits","to":"b-what","type":"detail"},{"id":"e18","from":"t-amend","to":"b-what","type":"detail"},{"id":"e19","from":"t-conflict40","to":"b-what","type":"detail"},{"id":"e20","from":"l-revenue","to":"b-what","type":"detail"},{"id":"e21","from":"l-income","to":"b-what","type":"detail"},{"id":"e30","from":"w-for","to":"b-who","type":"detail"},{"id":"e31","from":"w-against","to":"b-who","type":"detail"},{"id":"e32","from":"a-brin","to":"b-who","type":"detail"},{"id":"e33","from":"wh-election","to":"b-when","type":"detail"},{"id":"e34","from":"t-date","to":"b-when","type":"detail"},{"id":"e35","from":"wh-review","to":"b-when","type":"detail"},{"id":"e36","from":"t-reform","to":"b-when","type":"detail"},{"id":"e37","from":"h-vote","to":"b-how","type":"detail"},{"id":"e38","from":"h-private","to":"b-how","type":"detail"},{"id":"c1","from":"x-revenue","to":"root","type":"crux"},{"id":"c2","from":"x-fair","to":"root","type":"crux"},{"id":"c3","from":"x-expand","to":"root","type":"crux"},{"id":"c4","from":"x-money","to":"root","type":"crux"},{"id":"c5","from":"x-effect","to":"root","type":"crux"},{"id":"e40","from":"a-100b","to":"x-revenue","type":"weighs","stance":"for","why":"If true, the revenue offsets health-care funding cuts."},{"id":"e41","from":"a-25b","to":"x-revenue","type":"weighs","stance":"against","why":"If true, the state ends up with less money, not more."},{"id":"e42","from":"l-revenue","to":"x-revenue","type":"weighs","stance":"mixed","why":"The official estimate sits between the two campaigns' numbers."},{"id":"e43","from":"a-fair","to":"x-fair","type":"weighs","stance":"for","why":"A fairness argument: the tax corrects lower effective rates."},{"id":"e44","from":"gl-wealth","to":"x-fair","type":"weighs","stance":"for","why":"The general principle the yes side relies on."},{"id":"e45","from":"g-retro","to":"x-fair","type":"weighs","stance":"mixed","why":"A fairness question about timing rather than about who pays."},{"id":"e46","from":"a-expand","to":"x-expand","type":"weighs","stance":"against","why":"A risk argument about future amendments."},{"id":"e47","from":"a-only","to":"x-expand","type":"weighs","stance":"for","why":"The proponents' answer to the expansion worry."},{"id":"e48","from":"a-retire","to":"x-expand","type":"weighs","stance":"against","why":"A precedent argument about retirement savings."},{"id":"e49","from":"a-schools","to":"x-money","type":"weighs","stance":"against","why":"An argument about school funding rules."},{"id":"e39","from":"a-safeguards","to":"x-money","type":"weighs","stance":"against","why":"An argument about how broadly the health money can be spent."},{"id":"e38b","from":"t-spend","to":"x-money","type":"weighs","stance":"mixed","why":"What the text actually allocates."},{"id":"e37b","from":"g-nullify","to":"x-effect","type":"weighs","stance":"mixed","why":"Your vote on 40 interacts with your votes on 41 and 42."},{"id":"e36b","from":"a-onetime","to":"x-effect","type":"weighs","stance":"against","why":"An argument about budget stability."},{"id":"e35b","from":"t-reform","to":"x-effect","type":"weighs","stance":"mixed","why":"If courts reject the dates, the act asks them to move the tax rather than void it."},{"id":"e50","from":"l-revenue","to":"a-100b","type":"challenges","why":"The Legislative Analyst's estimate is far lower than the campaign's figure and spread across several years."},{"id":"e51","from":"f-wealth","to":"a-100b","type":"supports","why":"The campaign's figure is the 5% rate applied to the findings' total, before exemptions, avoidance, or departures."},{"id":"e52","from":"f-rates","to":"a-fair","type":"supports","why":"The measure's own findings make this comparison, citing an NBER paper."},{"id":"e53","from":"gl-wealth","to":"a-fair","type":"appliesTo","why":"The argument assumes untaxed gains are unfair. That premise recurs in every wealth-tax debate."},{"id":"e60","from":"l-income","to":"a-25b","type":"challenges","why":"The Legislative Analyst expects a much smaller yearly income-tax loss than the opponents' figure implies."},{"id":"e61","from":"gl-flight","to":"a-25b","type":"appliesTo","why":"The opponents' revenue-loss estimate depends on billionaires leaving. This is the general claim that they do."},{"id":"e62","from":"gl-flight","to":"l-income","type":"appliesTo","why":"The LAO also expects some departures, at a smaller scale."},{"id":"e70","from":"t-amend","to":"a-expand","type":"supports","why":"The text does let the Legislature amend the act without returning to voters."},{"id":"e71","from":"t-purpose","to":"a-expand","type":"qualifies","why":"Amendments must further the act's purposes, which it describes as a “narrowly applicable, one-time tax.”"},{"id":"e72","from":"a-only","to":"a-expand","type":"challenges","why":"The proponents' rebuttal says the tax can't reach anyone else."},{"id":"e73","from":"t-amend","to":"a-only","type":"qualifies","why":"“Cannot” is stronger than the text, which allows amendments within its purposes."},{"id":"e74","from":"q-expand","to":"t-amend","type":"asks"},{"id":"e80","from":"g-retire","to":"a-retire","type":"qualifies","why":"Correct for the largest Roth balances. Not correct for pensions and IRAs."},{"id":"e81","from":"t-retire","to":"g-retire","type":"supports","why":"The exemption and its Roth exception."},{"id":"e85","from":"t-limits","to":"a-schools","type":"supports","why":"The revenue is excluded from the school-funding formula in Art. XVI §8."},{"id":"e86","from":"t-spend","to":"a-schools","type":"qualifies","why":"10% goes to an education and food account, outside the formula."},{"id":"e87","from":"t-supplant","to":"a-safeguards","type":"challenges","why":"The text forbids using the money to replace existing funding. It doesn't say who the payments go to."},{"id":"e88","from":"a-safeguards","to":"t-spend","type":"challenges","why":"The argument says the health account's uses are too broad."},{"id":"e90","from":"t-installments","to":"a-onetime","type":"qualifies","why":"Payments can arrive over five years."},{"id":"e91","from":"t-oda","to":"a-onetime","type":"qualifies","why":"Deferred amounts can be collected much later, even from an estate."},{"id":"e95","from":"t-date","to":"g-retro","type":"supports","why":"The dates themselves."},{"id":"e96","from":"gl-prospective","to":"g-retro","type":"appliesTo","why":"If taxes should only apply prospectively, the January 1 date is a problem."},{"id":"e97","from":"rec-42","to":"g-retro","type":"conflicts","why":"Prop 42 bans taxes keyed to residency before the tax took effect."},{"id":"e98","from":"q-movers","to":"t-date","type":"asks"},{"id":"e99","from":"g-movers","to":"q-movers","type":"answers","why":"From the apportionment rules."},{"id":"e100","from":"t-reform","to":"g-retro","type":"qualifies","why":"If a court rejects the date, the act asks it to move the tax later rather than void it."},{"id":"e110","from":"rec-41","to":"g-nullify","type":"supports","why":"Prop 40 excludes its revenue from the spending limit, which triggers Prop 41's conflict clause."},{"id":"e111","from":"rec-42","to":"g-nullify","type":"supports","why":"Prop 42's conflict clause covers taxes on “individually owned assets” and taxes based on a past status. Prop 40 is both."},{"id":"e112","from":"t-conflict40","to":"g-nullify","type":"qualifies","why":"Prop 40 claims the reverse if it gets more yes votes. Courts would decide how the clauses interact."},{"id":"e113","from":"t-limits","to":"rec-41","type":"conflicts","why":"This is the exclusion Prop 41 targets."},{"id":"eh0","from":"x-history","to":"root","type":"crux"},{"id":"eh1","from":"p-mhsa","to":"x-history","type":"weighs","stance":"mixed","why":"California has dedicated a tax on its highest earners to health services before; it was a tax on income, not on wealth."},{"id":"eh2","from":"p-unspent","to":"x-history","type":"weighs","stance":"against","why":"The earlier earmarked tax raised money, but the state did not make sure it was spent on time."},{"id":"eh3","from":"p-temporary","to":"x-history","type":"weighs","stance":"against","why":"A tax sold as temporary was later extended by voters."},{"id":"eh4","from":"p-volatile","to":"x-history","type":"weighs","stance":"mixed","why":"Earlier taxes on the richest Californians raised money, but how much moved with the markets."},{"id":"eh5","from":"p-unspent","to":"a-safeguards","type":"supports","why":"Both measures earmark a tax on the very rich for health. The audit shows earmarked money can sit unused when oversight is weak; Prop 40's spending rules differ, so it shows a risk, not an outcome."},{"id":"eh6","from":"p-temporary","to":"a-onetime","type":"supports","why":"Prop 30 was written as temporary and was extended at the ballot. Prop 40 is written as a one-time tax, so the parallel is to later political pressure, not to anything in its text."},{"id":"eh7","from":"p-volatile","to":"a-100b","type":"qualifies","why":"Prop 55 taxed income and Prop 40 taxes wealth, but both depend on what the richest Californians' assets are worth, which moves with markets."},{"id":"eh8","from":"p-unspent","to":"x-money","type":"weighs","stance":"against","why":"The closest earlier case of a tax on the very rich set aside for health, where the audit found money left unspent."},{"id":"ec1","from":"t-conflict40","to":"rec-41","type":"conflicts","why":"Prop 40's conflict rule decides what happens if Prop 41 also passes."},{"id":"ec2","from":"t-conflict40","to":"rec-42","type":"conflicts","why":"Prop 40's conflict rule decides what happens if Prop 42 also passes."}],"sources":[{"id":"law-40","number":"40","role":"legal-text","url":"https://vig.cdn.sos.ca.gov/2026/general/pdf/prop40-text-proposed-laws.pdf","locator":"Proposition 40, full proposed law; see claim-specific section locators","retrievedAt":"2026-10-11T20:44:11.462Z","hash":"a2de24bb944c10590e83bae595461c0c21962a720b6c3459f6650d28d5d293da","documentHash":"07afc5d301b6d0612440ed094d27acb2ff3ab813fb44b374aa8479a210890c68"},{"id":"analysis-40","number":"40","role":"official-analysis","url":"https://voterguide.sos.ca.gov/propositions/40/analysis.htm","locator":"Proposition 40, official LAO analysis including image descriptions","retrievedAt":"2026-10-11T20:44:11.462Z","hash":"47a2b42e1f5f7b155ac8f98c9475f66d336d767091f9aa00d71c6015311747c5","documentHash":"47a2b42e1f5f7b155ac8f98c9475f66d336d767091f9aa00d71c6015311747c5"},{"id":"arguments-40","number":"40","role":"official-arguments","url":"https://voterguide.sos.ca.gov/propositions/40/arguments-rebuttals.htm","locator":"Proposition 40, official arguments and rebuttals","retrievedAt":"2026-10-11T20:44:11.520Z","hash":"9cdfb4b8ac1bd5c442db2a20d4150d71ccb8925d23d1a4356c50d6c7934a068d","documentHash":"9cdfb4b8ac1bd5c442db2a20d4150d71ccb8925d23d1a4356c50d6c7934a068d"},{"id":"law-41","number":"41","role":"legal-text","url":"https://vig.cdn.sos.ca.gov/2026/general/pdf/prop41-text-proposed-laws.pdf","locator":"Proposition 41, full proposed law; see claim-specific section locators","retrievedAt":"2026-10-11T20:44:11.667Z","hash":"85d26c25345f4e5464210fab1a5d62360271be67c6ff1e65d4d15a9f5c678fd9","documentHash":"c5126121aa12fa592bb5a430f12270a4f2c6962fd22f8106c95089062275b9e8"},{"id":"law-42","number":"42","role":"legal-text","url":"https://vig.cdn.sos.ca.gov/2026/general/pdf/prop42-text-proposed-laws.pdf","locator":"Proposition 42, full proposed law; see claim-specific section locators","retrievedAt":"2026-10-11T20:44:11.800Z","hash":"2c97f4b91c8e1394dd673058332c265c17239a37db234897bd5a333680a8bc6f","documentHash":"21c9d7e166220d9609eb0e9e85d050c2f0a8dedfc15b07e4690d2a5ed48bb111"},{"id":"precedent-mhsa-audit","number":"40","role":"precedent","url":"https://information.auditor.ca.gov/pdfs/reports/2017-117.pdf","title":"State Auditor, Report 2017-117: Mental Health Services Act (February 2018)","locator":"Summary, report pages 1–2 (PDF pages 7–8)","retrievedAt":"2026-10-13T02:33:11.006Z","hash":"0f17264380a68a411d4e7bedeb40f616731064fc58a80c0bd31f43b55ef37848","documentHash":"3cdcf511350fab40ba689ead8d0e97dfba077040c32d928297b7509d75583a6e"},{"id":"precedent-prop55","number":"40","role":"precedent","url":"https://www.lao.ca.gov/ballot/2016/Prop55-110816.pdf","title":"Legislative Analyst, Proposition 55 analysis (November 2016 ballot)","locator":"Yes/No statement and fiscal analysis","retrievedAt":"2026-10-13T02:33:11.301Z","hash":"49e016d0e38bfc5eab649e9659b7dac89f2773d090670e141f744deb4cb4e302","documentHash":"01dd70a635a49d7db279a44a217c536f35c2b61af35e1382982dcaedfb6ef820"}],"verification":{"state":"unverified"},"generation":{"promptVersion":"trillion-design-pilot","model":"claude-opus-5-5 (assembled from the design prototype)","inputHash":"7dd724672de666f946d50d28c8efefade8bcc64ee4ee902fedfd9ab6698f259d","generatedAt":"2026-10-12T01:41:45.753Z"}};
